def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])

    # The 5s along the bottom edge send a ray upward. Each nonzero
    # cell encountered becomes the color carried by the ray.
    for c in range(w):
        if out[h - 1][c] == 5:
            color = 5
            for r in range(h - 2, -1, -1):
                if out[r][c] != 0:
                    color = out[r][c]
                else:
                    out[r][c] = color

    return out
